package com.varnalabs.mobile;
import android.media.*;import java.nio.*;import java.io.*;import org.json.*;import java.util.function.BooleanSupplier;
/** Decode local source audio, mix on the project clock, then encode one stereo AAC track. */
final class AudioRenderer {
 static final int RATE=48000;static File render(MainActivity a,JSONArray clips,double duration,BooleanSupplier cancelled)throws Exception{if(clips.length()==0)return null;if(clips.length()>64)throw new IOException("Audio export supports 64 clips");int length=(int)Math.ceil(duration*RATE);float[] mix=new float[length*2];boolean hasAudio=false;for(int i=0;i<clips.length();i++)hasAudio|=decode(a,clips.getJSONObject(i),mix,length,cancelled);if(!hasAudio)return null;File out=new File(a.getCacheDir(),"audio56-"+System.nanoTime()+".m4a");MediaCodec codec=null;MediaMuxer mux=null;boolean started=false,success=false;try{MediaFormat f=MediaFormat.createAudioFormat("audio/mp4a-latm",RATE,2);f.setInteger(MediaFormat.KEY_AAC_PROFILE,MediaCodecInfo.CodecProfileLevel.AACObjectLC);f.setInteger(MediaFormat.KEY_BIT_RATE,192000);f.setInteger(MediaFormat.KEY_MAX_INPUT_SIZE,16384);codec=MediaCodec.createEncoderByType("audio/mp4a-latm");codec.configure(f,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);codec.start();mux=new MediaMuxer(out.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);int offset=0,track=-1;boolean inputEnd=false,outputEnd=false;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long deadline=System.currentTimeMillis()+120000;while(!outputEnd){if(cancelled.getAsBoolean())throw new IOException("Export cancelled");if(System.currentTimeMillis()>deadline)throw new IOException("AAC encoding timeout");if(!inputEnd){int index=codec.dequeueInputBuffer(10000);if(index>=0){ByteBuffer b=codec.getInputBuffer(index).order(ByteOrder.LITTLE_ENDIAN);int count=Math.min(b.capacity()/4,length-offset);b.clear();for(int n=0;n<count*2;n++)b.putShort((short)Math.round(Math.max(-1,Math.min(1,mix[offset*2+n]))*32767));codec.queueInputBuffer(index,0,count*4,(long)offset*1000000/RATE,count==0?MediaCodec.BUFFER_FLAG_END_OF_STREAM:0);offset+=count;if(count==0)inputEnd=true;}}int index=codec.dequeueOutputBuffer(info,10000);if(index==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){track=mux.addTrack(codec.getOutputFormat());mux.start();started=true;}else if(index>=0){ByteBuffer b=codec.getOutputBuffer(index);if((info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)!=0)info.size=0;if(info.size>0){if(!started)throw new IOException("AAC format not ready");b.position(info.offset);b.limit(info.offset+info.size);mux.writeSampleData(track,b,info);}outputEnd=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(index,false);}}success=true;return out;}finally{if(codec!=null){try{codec.stop();}finally{codec.release();}}if(mux!=null){if(started)mux.stop();mux.release();}if(!success)out.delete();}}
 static boolean decode(MainActivity a,JSONObject c,float[] mix,int length,BooleanSupplier cancelled)throws Exception{String id=c.getString("assetId");double start=c.getDouble("start"),in=c.getDouble("in"),out=c.getDouble("out"),gain=c.optDouble("gain",1),fadeIn=c.optDouble("fadeIn",0),fadeOut=c.optDouble("fadeOut",0);if(!Double.isFinite(start)||!Double.isFinite(in)||!Double.isFinite(out)||!Double.isFinite(gain)||start<0||in<0||out<=in||gain<0||gain>3)throw new IOException("Invalid audio timing");if(gain==0)return false;MediaExtractor source=new MediaExtractor();MediaCodec decoder=null;try{source.setDataSource(a.mediaFile(id).getAbsolutePath());int track=-1;for(int n=0;n<source.getTrackCount();n++)if(source.getTrackFormat(n).getString(MediaFormat.KEY_MIME).startsWith("audio/")){track=n;break;}if(track<0)return false;source.selectTrack(track);source.seekTo((long)(in*1000000),MediaExtractor.SEEK_TO_PREVIOUS_SYNC);MediaFormat format=source.getTrackFormat(track);decoder=MediaCodec.createDecoderByType(format.getString(MediaFormat.KEY_MIME));decoder.configure(format,null,null,0);decoder.start();int rate=format.getInteger(MediaFormat.KEY_SAMPLE_RATE),channels=format.getInteger(MediaFormat.KEY_CHANNEL_COUNT),encoding=2;boolean inputEnd=false,outputEnd=false;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long deadline=System.currentTimeMillis()+120000;while(!outputEnd){if(cancelled.getAsBoolean())throw new IOException("Export cancelled");if(System.currentTimeMillis()>deadline)throw new IOException("Audio decode timeout");if(!inputEnd){int i=decoder.dequeueInputBuffer(10000);if(i>=0){ByteBuffer b=decoder.getInputBuffer(i);long pts=source.getSampleTime();int n=pts>=(long)(out*1000000)?-1:source.readSampleData(b,0);if(n<0){decoder.queueInputBuffer(i,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inputEnd=true;}else{decoder.queueInputBuffer(i,0,n,pts,0);source.advance();}}}int i=decoder.dequeueOutputBuffer(info,10000);if(i==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){format=decoder.getOutputFormat();rate=format.getInteger(MediaFormat.KEY_SAMPLE_RATE);channels=format.getInteger(MediaFormat.KEY_CHANNEL_COUNT);encoding=format.containsKey(MediaFormat.KEY_PCM_ENCODING)?format.getInteger(MediaFormat.KEY_PCM_ENCODING):2;if(encoding!=2&&encoding!=4)throw new IOException("Unsupported decoded PCM format");}else if(i>=0){ByteBuffer b=decoder.getOutputBuffer(i).order(ByteOrder.LITTLE_ENDIAN);int bytes=encoding==4?4:2,frames=info.size/(channels*bytes);double sourceTime=info.presentationTimeUs/1000000.0;int first=Math.max(0,(int)Math.ceil((start+sourceTime-in)*RATE)),last=Math.min(length,(int)Math.ceil((start+sourceTime-in+(double)frames/rate)*RATE));for(int frame=first;frame<last;frame++){double t=(double)frame/RATE-start+in;if(t<in||t>=out)continue;int n=(int)Math.round((t-sourceTime)*rate);if(n<0||n>=frames)continue;double gainAt=gain*Math.min(1,Math.min(fadeIn>0?(t-in)/fadeIn:1,fadeOut>0?(out-t)/fadeOut:1));for(int channel=0;channel<2;channel++){int pos=info.offset+(n*channels+Math.min(channel,channels-1))*bytes;float v=encoding==4?b.getFloat(pos):b.getShort(pos)/32768f;mix[frame*2+channel]+=(float)(v*gainAt);}}outputEnd=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;decoder.releaseOutputBuffer(i,false);}}return true;}finally{if(decoder!=null){try{decoder.stop();}finally{decoder.release();}}source.release();}}
}
